const transaction = (context.get('transaction') || 0) + 1;
context.set('transaction', transaction & 0xffff);
const mbap = Buffer.from([(transaction >> 8) & 0xff, transaction & 0xff, 0, 0, 0, 6, 1]);
const pdu = Buffer.from([3, 0, 0, 0, 1]);
msg.payload = Buffer.concat([mbap, pdu]);
return msg;

const frame = Buffer.from(msg.payload || []);
if (frame.length < 11) { node.error('Resposta Modbus incompleta'); return null; }
if ((frame[7] & 0x80) !== 0) { node.error(`Exceção Modbus ${frame[8]}`); return null; }
const value = frame.readUInt16BE(9);
msg.payload = { source: 'modbus-virtual', register: 'holding[0]', loaded_quantity: value, communication: 'ONLINE', safe: true };
return msg;
